/* Project presentation authority. Financial records and transactions remain in project-engine.js. */
const psProjectLabSections={'Overview':'Dashboard','Orders & Pricing':'Orders & pricing','Extras & Approvals':'Extras & approvals','Costing & Margin':'Costs & margin','Billing & Variations':'Invoices','Correspondence':'Correspondence','Scope & Tasks':'Scope & tasks','Materials':'Materials','Procurement':'Purchasing','Stock & Job Bin':'Stock & job bin','Tools':'Tools','Site Notes & Files':'Files & site notes','Activity':'Activity','Settings':'Settings'};
function psProjectLabPanel(title,body,subtitle=''){return '<section class="pl-panel"><header><h3>'+psProjectEsc(title)+'</h3>'+(subtitle?'<p>'+psProjectEsc(subtitle)+'</p>':'')+'</header>'+body+'</section>';}
function psProjectLabTimeline(p,limit=1000){const entries=p.correspondence.slice().sort((a,b)=>Date.parse(b.occurredAt)-Date.parse(a.occurredAt)).slice(0,limit);return '<div class="pl-timeline">'+(entries.map(c=>'<article><small>'+psProjectEsc(new Date(c.occurredAt).toLocaleString('en-GB',{timeZone:'Europe/London'}))+' · UK time · '+psProjectEsc(c.user||'')+'</small><h4>'+psProjectEsc(c.type)+' · '+psProjectEsc(c.contact)+'</h4><span class="pl-tag">'+psProjectEsc(p.variations.find(v=>v.id===c.variationId)?.title||'Original scope')+'</span><p>'+psProjectEsc(c.body)+'</p><small>'+psProjectEsc(c.source||'Manual record')+'</small>'+(c.followUp?'<div class="pl-followup">Follow-up '+psProjectEsc(c.followUp)+(c.completedAt?' · Completed':' <button data-project-followup="'+psProjectEsc(c.id)+'">Complete follow-up</button>')+'</div>':'')+'</article>').join('')||'<p>No conversations recorded. Log a call, email or site discussion to start the project history.</p>')+'</div>';}
function psProjectLabMetrics(p,s){const ready=p.phases.filter(ph=>ph.ready&&!ph.invoiceRequested).reduce((n,ph)=>n+psProjectPence(ph.amountNet),0);return '<div class="pl-metrics">'+[['Agreed project value',psProjectCash(s.revenue),'Original quote + approved extras'],['Forecast final cost',psProjectCash(s.forecast),'Actual, committed and remaining'],['Forecast profit',s.margin===null?'Not set':psProjectCash(s.profit),s.missingCosts?'Incomplete costs: review required':'After all forecast costs'],['Ready for invoice review',psProjectCash(ready),'Completed, unqueued stages']].map(([label,value,help])=>'<article><span>'+label+'</span><strong>'+value+'</strong><small>'+help+'</small></article>').join('')+'</div>';}
function psProjectLabDashboard(job,p,s){const tone=s.missingCosts||s.margin===null?'warn':s.margin<s.minimumMargin?'bad':s.margin<Number(p.warningMargin)?'warn':'good',headroom=Math.round(s.revenue*(1-s.minimumMargin/100))-s.forecast;
const band='<section class="pl-health '+tone+'"><div><span>Forecast margin</span><strong>'+(s.missingCosts?'Unverified':s.margin===null?'Not set':s.margin.toFixed(1)+'%')+'</strong></div><div><h3>'+(s.missingCosts?'Review missing costs':s.margin===null?'Set the agreed project value':tone==='bad'?'Action needed: below minimum margin':tone==='warn'?'Margin needs attention':'Project margin is healthy')+'</h3><p>Minimum '+s.minimumMargin+'% · Warning '+p.warningMargin+'% · Target '+s.target+'%</p><small>'+psProjectCash(Math.abs(headroom))+(headroom<0?' above the minimum-margin cost ceiling':' headroom before the minimum')+' · Risk buffer '+money(p.riskBufferNet||0)+'</small></div></section>';
const flow='<div class="pl-flow" aria-label="Project lifecycle">'+[['Quote',p.quoteAccepted?'Accepted':'Awaiting acceptance'],['Orders',s.orders.length+' linked'],['Purchasing',s.poRows.length+' linked'],['Delivery',psProjectStage(job.status)],['Invoicing',p.phases.filter(x=>x.invoiceRequested).length+' stages queued']].map(([t,v],i)=>'<div><small>0'+(i+1)+' · '+t+'</small><b>'+psProjectEsc(v)+'</b></div>').join('')+'</div>';
const attention='<div class="pl-attention">'+(s.alerts.map(a=>'<article class="'+psProjectEsc(a.severity)+'"><span aria-hidden="true">!</span><p>'+psProjectEsc(a.text)+'</p></article>').join('')||'<article class="good"><span aria-hidden="true">✓</span><p>No current commercial exceptions. Keep remaining costs up to date as work progresses.</p></article>')+'</div>';
const scope=psProjectTable(['Scope','Selling value'],[['Original accepted quote',s.quote],['Approved extras',s.approvedExtra],['Awaiting approval (excluded)',s.pendingExtra]].map(([t,v])=>'<tr><td>'+t+'</td><td>'+psProjectCash(v)+'</td></tr>').join(''));
const costs=psProjectTable(['Cost position','Ex VAT'],[['Actual recorded',s.actual],['Received estimates',s.estimatedReceived],['Outstanding commitments',s.committed],['Remaining forecast',s.uncommitted],['Tools and hire',s.tools]].map(([t,v])=>'<tr><td>'+t+'</td><td>'+psProjectCash(v)+'</td></tr>').join(''));
const quick='<div class="pl-quick">'+[[psProjectCorrespondence(job,p),'correspondence'],[psProjectCosting(job,p,s),'time'],[psProjectExtras(job,p,s),'variation']].map(([html,action])=>{const form=html.match(new RegExp('<form data-project-form="'+action+'"[\\s\\S]*?<\/form>'));return form?psProjectLabFocusForms(form[0]):'';}).join('')+'</div>';
return quick+flow+band+psProjectLabMetrics(p,s)+'<div class="pl-grid">'+psProjectLabPanel('What needs attention',attention,'Live checks from project records')+psProjectLabPanel('Original scope & extras',scope,'Only customer-approved extras increase agreed revenue')+psProjectLabPanel('Cost breakdown',costs,'Each cost source is counted once')+psProjectLabPanel('Latest correspondence',psProjectLabTimeline(p,3),'Calls, emails and site conversations')+'</div>'+psProjectLabPanel('Invoice recommendations','<div class="pl-pad">'+(s.recommendations.map(x=>'<p>'+psProjectEsc(x.text)+'</p>').join('')||'<p>No ready, unqueued stages. Maintain agreed milestones in Invoices.</p>')+'</div>');}
function psProjectLabFocusForms(html){return html.replace(/<form data-project-form="([^"]+)"[\s\S]*?<\/form>/g,(form,action)=>{if(action==='settings')return form;const names={time:'Record labour',cost:'Record cost',forecast:'Update remaining forecast',variation:'Add requested extra',correspondence:'Log conversation',link:'Allocate sales order',phase:'Add invoice stage','tool-add':'Add equipment','tool-stop':'Set final charge date','tool-return':'Confirm return',task:'Add task','material-plan':'Add material plan','stock-use':'Record stock use','stock-damage':'Record damage'};return '<div class="pl-entry"><button data-pl-form="'+action+'">'+(names[action]||'Add record')+'</button><template data-pl-template="'+action+'">'+form+'</template></div>';});}
function psProjectLabWorkspace(job,p,s,body){if(psProjectTab==='Overview')body=psProjectLabDashboard(job,p,s);else if(psProjectTab==='Correspondence'){const old=body.match(/<form data-project-form="correspondence"[\s\S]*?<\/form>/);body=psProjectLabPanel('Correspondence',psProjectLabTimeline(p)+(old?old[0]:''),'A dated record of conversations, agreements and follow-ups');}
body=body.replace(/<header class="project-profit-heading">[\s\S]*?<\/header>/,'');body=psProjectLabFocusForms(body);
const navigation='<nav class="pl-record-nav" aria-label="This project">'+Object.entries(psProjectLabSections).map(([key,label])=>'<button type="button" data-project-tab="'+psProjectEsc(key)+'" aria-current="'+(psProjectTab===key?'page':'false')+'">'+psProjectEsc(label)+'</button>').join('')+'</nav>';
return '<section class="ps-project-lab"><header class="pl-heading"><div><button class="secondary" data-project-back>Back to projects</button><span class="pl-eyebrow">PROJECT WORKSPACE · '+psProjectEsc(job.id)+'</span><h1>'+psProjectEsc(job.name)+'</h1><p>'+psProjectEsc(customer(job.customerId)?.name||'No customer')+' <span>·</span> '+psProjectEsc(job.status)+' <span>·</span> '+psProjectEsc(job.owner||'Owner unassigned')+'</p></div><button class="secondary" data-project-report>Export project report</button></header>'+navigation+'<div class="pl-section-heading"><h2>'+psProjectEsc(psProjectLabSections[psProjectTab]||psProjectTab)+'</h2><span>All financial values exclude VAT</span></div><div class="pl-content">'+body+'</div></section>';}
(function(){const route=openSidebarSubGroup;openSidebarSubGroup=function(id,section){if(id==='jobs'&&['Projects','Job List','All projects'].includes(section)){if(!canAccessTab('jobs'))return toast('You do not have access to Projects.');psProjectSelected='';psProjectTab='Overview';return route(id,'Projects');}return route(id,section);};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-pl-close')){const d=b.closest('dialog');d.close();d.remove();return;}if(!b.hasAttribute('data-pl-form'))return;const action=b.dataset.plForm,template=b.parentElement.querySelector('template');if(!template)return;document.getElementById('psProjectEntryDialog')?.remove();const d=document.createElement('dialog');d.id='psProjectEntryDialog';d.className='ps-project-lab pl-dialog';d.setAttribute('aria-labelledby','pl-dialog-title');d.innerHTML='<header><div><span class="pl-eyebrow">PROJECT RECORD</span><h2 id="pl-dialog-title">'+psProjectEsc(b.textContent)+'</h2></div><button class="secondary" data-pl-close aria-label="Close dialog">Close</button></header>'+template.innerHTML;document.body.appendChild(d);d.addEventListener('cancel',()=>d.remove());d.addEventListener('close',()=>{d.remove();b.focus();},{once:true});d.showModal();});})();
